@app.route("/teacher/tools")
def teacher_tools():
    tab = request.args.get("tab", "overview")
    if tab not in TEACHER_WORKSPACE_TITLES:
        tab = "overview"
    return render_teacher_workspace(tab, TEACHER_WORKSPACE_TITLES[tab])

